import { Controller, Get, Param, Logger } from "@nestjs/common";
import { ConnectQuestService } from "./connect-quest.service";
import { ApiTags, ApiOperation, ApiOkResponse, ApiNotFoundResponse } from "@nestjs/swagger";

/**
* Klasse: ConnectQuestController
*
* Diese Controller-Klasse verwaltet die Endpunkte rund um den one time Pin
* zur Verbindung der Quest.
*/

@ApiTags("Connect Quest")
@Controller("connect-quest")
export class ConnectQuestController {
    private readonly logger = new Logger(ConnectQuestController.name);

  constructor(private readonly connectQuestService: ConnectQuestService) {}

  /**
   * Funktion: getPin
   *
   * Gibt den aktuellsten verfügbaren PIN zurück, um eine Quest zu verbinden.
   * Die PIN wird aus Redis gelesen, falls vorhanden.
   *
   * @returns Der neueste PIN als Zeichenkette
   */
  // GET /connect-quest/pin
  @Get("pin")
  @ApiOperation({
    summary: "Liefert den aktuellen PIN",
    description: "Gibt die aktuell gespeicherte PIN zurück, die zur Verbindung mit einer Quest genutzt werden kann.",
  })
  @ApiOkResponse({
    type: String,
    description: "Die aktuell gültige PIN.",
  })
  async getPin(): Promise<string> {
    return await this.connectQuestService.getPin();
  }

  /**
   * Funktion: getPerPin
   *
   * Sucht nach einem bestimmten PIN und gibt den JWT, die CourseProgressID und die ID des
   * aufrufenden Users zurück, falls vorhanden. Die Informationen werden aus Redis gelesen.
   *
   * @param pin - Der zu suchende PIN
   * @returns JWT, die CourseProgressID und die ID des
   * aufrufenden Users zur PIN oder undefined, wenn nicht gefunden
   */
  // GET /connect-quest/pin/:pin
  @Get("pin/:pin")
  @ApiOperation({
    summary: "Suche nach PIN",
    description: "Findet und gibt den JWT, die CourseProgressID und die ID des aufrufenden Users zur übergebenen PIN zurück, falls vorhanden.",
  })
  @ApiOkResponse({
    type: String,
    description: "Daten zur PIN: den JWT, die CourseProgressID und die ID des aufrufenden Users.",
  })
  @ApiNotFoundResponse({
    description: "PIN wurde nicht gefunden oder ist ungültig.",
  })
  async getPerPin(@Param("pin") pin: string): Promise<string | undefined> {
    const parsedPin = parseInt(pin, 10);
    return await this.connectQuestService.getPerPin(parsedPin);
  }
}